import sys
from collections import defaultdict, deque

def solve():
    try:
        line1 = sys.stdin.readline().strip()
        if not line1:
            return
        n, k = map(int, line1.split())

        adj = defaultdict(list)
        in_degree = {chr(ord('a') + i): 0 for i in range(k)}
        present_chars = set()

        for _ in range(n):
            word = sys.stdin.readline().strip()
            for c in word:
                present_chars.add(c)

        for i in range(n - 1):
            w1 = sys.stdin.readline().strip()
            w2 = sys.stdin.readline().strip()

            min_len = min(len(w1), len(w2))
            found = False
            for j in range(min_len):
                if w1[j] != w2[j]:
                    u, v = w1[j], w2[j]
                    if v not in adj[u]:
                        adj[u].append(v)
                        in_degree[v] += 1
                    found = True
                    break

        queue = deque()
        for char in in_degree:
            if char in present_chars and in_degree[char] == 0:
                queue.append(char)

        result = []
        while queue:
            node = queue.popleft()
            result.append(node)
            for neighbor in adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(result) < len(present_chars):
            print("0")
        else:
            order_str = "".join(result)
            valid = True
            for i in range(n - 1):
                w1 = sys.stdin.readline().strip()
                w2 = sys.stdin.readline().strip()

                min_len = min(len(w1), len(w2))
                found_diff = False
                for j in range(min_len):
                    if w1[j] != w2[j]:
                        idx_u = order_str.find(w1[j])
                        idx_v = order_str.find(w2[j])
                        if idx_u > idx_v:
                            valid = False
                            break
                        found_diff = True
                        break

                if not found_diff and len(w1) > len(w2):
                    valid = False

                if not valid:
                    break

            if valid:
                print("1")
            else:
                print("0")

    except Exception:
        print("0")

if __name__ == "__main__":
    solve()
